use vstd::prelude::*;
use vstd::vec::*;

verus! {

pub fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        // Result contains two matrices
        result.0.len() == y.len(),
        result.1.len() == y.len(),
        // All rows have correct length
        forall|i: int| 0 <= i < y.len() ==> result.0[i].len() == x.len(),
        forall|i: int| 0 <= i < y.len() ==> result.1[i].len() == x.len(),
        // First matrix elements match x values
        forall|i: int, j: int| 
            0 <= i < y.len() && 0 <= j < x.len() ==> 
            result.0[i][j] == x[j],
        // Second matrix elements match y values
        forall|i: int, j: int| 
            0 <= i < y.len() && 0 <= j < x.len() ==> 
            result.1[i][j] == y[i],
{
    let m = y.len();
    let n = x.len();
    
    // Create first matrix (X grid)
    let mut x_grid: Vec<Vec<f32>> = Vec::new();
    let mut i: usize = 0;
    
    while i < m
        invariant
            0 <= i <= m,
            x_grid.len() == i,
            forall|k: int| 0 <= k < i ==> x_grid[k].len() == n,
            forall|k: int, l: int| 
                0 <= k < i && 0 <= l < n ==> 
                x_grid[k][l] == x[l],
    {
        let mut row: Vec<f32> = Vec::new();
        let mut j: usize = 0;
        
        while j < n
            invariant
                0 <= j <= n,
                row.len() == j,
                forall|k: int| 0 <= k < j ==> row[k] == x[k],
        {
            row.push(x[j]);
            j = j + 1;
        }
        
        x_grid.push(row);
        i = i + 1;
    }
    
    // Create second matrix (Y grid)
    let mut y_grid: Vec<Vec<f32>> = Vec::new();
    let mut i: usize = 0;
    
    while i < m
        invariant
            0 <= i <= m,
            y_grid.len() == i,
            forall|k: int| 0 <= k < i ==> y_grid[k].len() == n,
            forall|k: int, l: int| 
                0 <= k < i && 0 <= l < n ==> 
                y_grid[k][l] == y[k],
    {
        let mut row: Vec<f32> = Vec::new();
        let mut j: usize = 0;
        
        while j < n
            invariant
                0 <= j <= n,
                row.len() == j,
                forall|k: int| 0 <= k < j ==> row[k] == y[i],
        {
            row.push(y[i]);
            j = j + 1;
        }
        
        y_grid.push(row);
        i = i + 1;
    }
    
    (x_grid, y_grid)
}

} // verus!